"""DEC-198 Amendment 4: manual resolution authority is generated by the backend review.

A client may submit only a manual value the server-generated review explicitly offers (an entry on that exact
item). Unsupported or Unverified engineering semantics -- a documented-but-unrepresentable boundary, a meaning
not yet verified -- a setting the relay does not have, and canonical paths the review does not show at all can
never be turned into an accepted value by a crafted request, on validation or on Apply. Genuine source-data
problems (a blank / missing or unreadable value) and the existing user corrections keep working. Suggestions
stay server-derived: the client names an item, never a value, and only an offered suggestion is accepted.
"""

from __future__ import annotations

import pytest

from app.domain.relay_import.provenance import UnresolvedCause
from app.domain.relay_import.review_state import (
    MANUAL_NOT_OFFERED,
    ReviewDecisionError,
    ReviewDecisions,
    apply_review,
    manual_entry_spec,
)
from app.services.relay_review_token import current_relay_knowledge
from app.services.relay_review_validation import InvalidReviewError, manual_entry_paths, validate_review
from tests import relay_family_fixtures as F
from tests.relay_conformance.harness import EXPECTATIONS_DIR, expectation_paths, load_expectation, sample_pdf
from tests.test_relay_import_upload import _p441_pdf
from tests.relay_api_helpers import APPLY, VALIDATE, client, decisions, items, upload  # noqa: F401

PP, COMMON, LEFT = "zones[Z1].resistive_reach.phase_phase", "zones[Z1].resistive_reach.common", "zones[Z1].resistive_reach.reverse"


def post(client, endpoint: str, review: dict, *, manual=(), suggested=(), confirm=False):
    body = decisions(review, confirm=confirm, suggested=False, manual=list(manual))
    body["suggested"] = list(suggested)
    return client.post(endpoint, json=body)


def refused(response) -> bool:
    return response.status_code == 400 and response.json()["detail"] == {"code": "invalid_review", "message": MANUAL_NOT_OFFERED}


@pytest.fixture(scope="module")
def sl87(client):
    return upload(client, F.sl87_pdf())["review"]


@pytest.fixture(scope="module")
def rel511(client):
    return upload(client, F.rel511_pdf())["review"]


class TestCraftedRequestsAreRefused:
    @pytest.mark.parametrize("endpoint", [VALIDATE, APPLY])
    def test_rel511_rfzn_plus_r_cannot_be_typed(self, client, rel511, endpoint):
        assert items(rel511)[PP]["category"] == "unsupported" and items(rel511)[PP]["resolution"] is None
        assert refused(post(client, endpoint, rel511, manual=[{"item_id": PP, "value": 2.3}]))

    @pytest.mark.parametrize("endpoint", [VALIDATE, APPLY])
    def test_7sl87_inclined_plus_r_cannot_be_typed(self, client, sl87, endpoint):
        assert items(sl87)[PP]["category"] == "unsupported" and items(sl87)[PP]["resolution"] is None
        assert refused(post(client, endpoint, sl87, manual=[{"item_id": PP, "value": 3.1}]))

    @pytest.mark.parametrize("endpoint", [VALIDATE, APPLY])
    def test_7sl87_left_boundary_cannot_be_typed_as_zero(self, client, sl87, endpoint):
        assert items(sl87)[LEFT]["resolution"] is None and items(sl87)[LEFT]["suggestion"] is None
        assert refused(post(client, endpoint, sl87, manual=[{"item_id": LEFT, "value": 0}]))

    @pytest.mark.parametrize(("review_name", "path"), [("sl87", COMMON), ("rel511", COMMON)])
    def test_a_path_the_review_does_not_show_cannot_be_typed(self, client, request, review_name, path):
        # the engine would take a common resistive reach as +R; the review never shows that item
        review = request.getfixturevalue(review_name)
        assert path not in items(review)
        assert refused(post(client, VALIDATE, review, manual=[{"item_id": path, "value": 3.1}]))
        assert refused(post(client, APPLY, review, manual=[{"item_id": path, "value": 3.1}]))

    def test_a_mapped_value_cannot_be_overwritten(self, client, sl87):
        assert refused(post(client, VALIDATE, sl87, manual=[{"item_id": "zones[Z1].x_reach_ohm", "value": 9.0}]))

    def test_a_not_exposed_selector_cannot_be_typed(self, client, sl87):
        assert items(sl87)["zones[Z2].characteristic.type"]["category"] == "not_exposed"
        r = post(client, VALIDATE, sl87, manual=[{"item_id": "zones[Z2].characteristic.type", "value": "quadrilateral"}])
        assert refused(r)

    def test_one_fabricated_entry_refuses_the_whole_request(self, client, sl87):
        manual = [{"item_id": "zones[Z1].phase_timer_s", "value": 0.15}, {"item_id": PP, "value": 3.1}]
        assert refused(post(client, VALIDATE, sl87, manual=manual))           # never silently ignored

    @pytest.mark.parametrize(("item", "message"), [
        ({"item_id": "zones[Z9].phase_timer_s", "value": 1.0}, "Unknown review item."),
        ({"item_id": "not a path", "value": 1.0}, "Unknown review item."),
        ({"item_id": "zones[Z1].phase_timer_s", "value": "soon"}, "A number is required."),
        ({"item_id": "zones[Z1].phase_timer_s", "value": -1.0}, "The value must be at least 0."),
    ])
    def test_malformed_or_wrong_path_entries_are_refused(self, client, sl87, item, message):
        r = post(client, VALIDATE, sl87, manual=[item])
        assert r.status_code == 400 and r.json()["detail"]["message"] == message


class TestSuggestionsStayServerDerived:
    def test_a_suggestion_the_review_does_not_offer_is_refused(self, client, sl87):
        r = post(client, VALIDATE, sl87, suggested=[LEFT])                    # 7SL87 -R: nothing offered
        assert r.status_code == 400
        r = post(client, VALIDATE, sl87, suggested=["zones[Z1].phase_timer_s"])   # no suggestion exists for a timer
        assert r.status_code == 400 and r.json()["detail"]["message"] == "No suggestion is available for this value."

    def test_an_offered_suggestion_still_works_through_apply(self, client):
        review = upload(client, F.rel670_pdf())["review"]                     # the 0.00 ohm visualization offer
        offered = [i["item_id"] for g in review["groups"] for i in g["items"] if i["item_id"] and i.get("suggestion")]
        assert offered
        body = decisions(review, manual=[{"item_id": "zones[Z2].phase_timer_s", "value": 1.0}])   # a genuine gap typed
        assert body["suggested"] == offered
        assert client.post(VALIDATE, json=body).json()["readiness"]["status"] == "ready"
        assert client.post(APPLY, json=body).status_code == 200


class TestLegitimateManualWorkflows:
    def test_a_blank_7sl87_timer_can_still_be_typed(self, client, sl87):
        timer = items(sl87)["zones[Z1].phase_timer_s"]
        assert timer["category"] == "missing" and timer["resolution"]["kind"] == "number"
        r = post(client, VALIDATE, sl87, manual=[{"item_id": "zones[Z1].phase_timer_s", "value": 0.15}])
        assert r.status_code == 200
        state = r.json()
        assert state["blocking_count"] == sl87["blocking_count"] - 1          # only the genuine source gap is cleared
        assert state["readiness"]["status"] == "not_ready"
        assert post(client, APPLY, sl87, manual=[{"item_id": "zones[Z1].phase_timer_s", "value": 0.15}]).status_code == 409

    def test_an_unreadable_cell_can_still_be_typed(self, client):
        # a malformed delay cell ("abc"); an "Infinity" cell is a configured value since DEC-198 Amendment 6
        model = _model(client, F.sa613_pdf(z1_delays=("abc", "")))
        unreadable = [p for p, s in model.iter_sourced() if not s.is_resolved and s.provenance.cause is UnresolvedCause.UNREADABLE
                      and manual_entry_spec(p, s) is not None]
        assert unreadable == ["zones[Z1].earth_timer_s"]
        apply_review(model, ReviewDecisions(manual={unreadable[0]: 1.0}), offered_manual=manual_entry_paths(model))

    def test_p441_zone_status_override_and_left_reach_still_reach_apply(self, client):
        review = upload(client, _p441_pdf())["review"]
        body = decisions(review)
        assert client.post(VALIDATE, json=body).json()["readiness"]["status"] == "ready"
        assert client.post(APPLY, json=body).status_code == 200
        status = next(i for g in review["groups"] for i in g["items"] if i["item_id"] == "zones[ZP].status")
        assert status["resolution"] is not None                               # an assumed status stays overridable
        r = post(client, VALIDATE, review, manual=[{"item_id": "zones[ZP].status", "value": "enabled"},
                                                    {"item_id": "zones[ZP].resistive_reach.reverse", "value": 0}])
        assert r.status_code == 200


def _verified(client, review: dict):
    """The server's interpretation as the upload's own signed token carries it (verified as the server does)."""
    return client.app.state.relay_review_signer.verify(
        review["validation_token"], import_id=review["import_id"], knowledge_for=current_relay_knowledge)


def _model(client, pdf: bytes):
    return _verified(client, upload(client, pdf)["review"])


SYNTHETIC_SAMPLES = sorted(p.stem for p in expectation_paths() if load_expectation(p)["sample"]["kind"] == "synthetic")

class TestEveryOfferedEntryAndNothingElse:
    """For every relay sheet: each item the server review offers an entry for is accepted, and every other
    canonical value in the interpretation is refused with the same generic message."""

    # every relay of the generic conformance set (DEC-199): its synthetic sheets, by expectation
    @pytest.mark.parametrize("name", SYNTHETIC_SAMPLES)
    def test_presentation_and_enforcement_agree(self, client, name):
        pdf = sample_pdf(load_expectation(EXPECTATIONS_DIR / f"{name}.json")["sample"])
        review = upload(client, pdf)["review"]
        original = _verified(client, review)
        signer = client.app.state.relay_review_signer

        def validate(decisions):
            return validate_review(review["validation_token"], review["import_id"], decisions, signer=signer)

        shown = {i["item_id"]: i for g in review["groups"] for i in g["items"] if i["item_id"] and i["primary"]}
        offered = {p for p, i in shown.items() if i["resolution"] is not None}
        assert offered == manual_entry_paths(original)                        # the server review is the authority
        for path in sorted(offered):
            res = shown[path]["resolution"]
            value = res["options"][0][0] if res["kind"] == "choice" else 1.0
            validate(ReviewDecisions(manual={path: value}))                   # accepted
        for path, _ in original.iter_sourced():
            if path in offered:
                continue
            with pytest.raises(InvalidReviewError, match=MANUAL_NOT_OFFERED):
                validate(ReviewDecisions(manual={path: 1.0}))


class TestDomainRule:
    def test_unsupported_and_unverified_values_are_never_typeable_even_without_the_review(self, client):
        model = _model(client, F.rel511_pdf())
        for path, sourced in model.iter_sourced():
            if not sourced.is_resolved and sourced.provenance.cause in (UnresolvedCause.UNSUPPORTED, UnresolvedCause.UNVERIFIED,
                                                                         UnresolvedCause.NOT_EXPOSED, UnresolvedCause.CONFLICT):
                assert manual_entry_spec(path, sourced) is None
                with pytest.raises(ReviewDecisionError, match=MANUAL_NOT_OFFERED):
                    apply_review(model, ReviewDecisions(manual={path: 1.0}))

    def test_decisions_are_judged_against_the_import_they_are_sent_with(self, client, sl87, rel511):
        # a 7SL87 timer entry is legitimate there; replayed with the REL511 context it is refused (REL511 states t1)
        entry = [{"item_id": "zones[Z1].phase_timer_s", "value": 0.15}]
        assert post(client, VALIDATE, sl87, manual=entry).status_code == 200
        assert refused(post(client, VALIDATE, rel511, manual=entry))
